import {runActionFlow} from './approved-flow.js';
import {esc,cash,icon,pageHead,row,field,btn,dateLabel} from './ui.js';
import {ensureAccountState,accountAccess,accountLoginConfigured,closureBlockers,supportSummary,supportRecordText} from './account-model.js';
import {createLoginCredential,derivePasswordProof,validateLoginPassword,normalizeUsername} from './login-credentials.js';
import {deviceAuthSupport,deviceCredentialStatus,registerDeviceCredential,authenticateDevice} from './device-auth.js';
import {bindAccountRecords,recordDateLabel} from './account-records.js';
import {getSupportDraft,clearSupportDraft,bindSupportDraft} from './account-support-drafts.js';
const route = page => ({section:'life',page});
const button = (label,page) => `<button class="button secondary" data-account-page="${esc(page)}">${esc(label)}</button>`;
const input=(label,name,value='',type='text',extras='')=>`<label class="field"><span>${esc(label)}</span><input class="input" name="${esc(name)}" value="${esc(value)}" type="${type}" ${extras} autocomplete="off"></label>`;
const pinInput=(label,name)=>input(label,name,'','password','inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required');
const error='<p class="error" data-account-error role="alert"></p>';
const accountNotice=ctx=>`<p class="account-local muted">${ctx.connected?'Shared test account · No live bank, SMS or support team is connected.':'Local prototype · No live bank, SMS or support service is connected.'}</p>`;
const head=(title,{home=true,back=true}={})=>pageHead(title,{back,action:home?'<button class="text-button" data-account-home>Home</button>':''});
function frame(ctx,title,body){const a=ensureAccountState(ctx.state),accessPage=title==='Welcome back',signedIn=ctx.state.onboardingDone===true&&!a.signedOut;return `<section class="page account-page ${accessPage?'auth-access-page':''}">${accessPage?(signedIn?head('',{home:true,back:false}):''):head(title,{home:signedIn,back:ctx.state.onboardingDone===true})}${a.status==='closed'?`<div class="notice"><span>This ${ctx.connected?'test':'demo'} account is closed. Its financial history is available to read and export.</span></div>`:''}${body}${accessPage?'':accountNotice(ctx)}</section>`;}
export function accountSettingsRows(ctx){return `<div class="section-label">Access & records</div><div class="panel">${[['account-security','lock','Security & access','Login, transaction PIN and phone biometrics'],['account-statements','download','Statements & data','Choose a period or download your records'],['account-support','chat','Your support reports','References, updates and payment help'],['account-privacy','eye','Privacy choices','Personalisation, marketing and requests'],['account-close','logout',ctx.connected?'Close this test account':'Close this demo account','Review money and keep your records']].map(([page,ic,title,sub])=>`<button class="row" data-account-page="${page}"><span class="row-icon">${icon(ic)}</span><span class="row-copy"><span class="row-title">${title}</span><span class="row-sub">${sub}</span></span>${icon('chevron',16)}</button>`).join('')}</div><button class="button secondary" data-account-signout>${icon('logout',18)} Sign out</button>`;}
function noSavedAccount(ctx){return frame(ctx,'Your saved account',`<div class="account-intro"><span class="account-icon">${icon('phone',34)}</span><h1>No saved account<br>in this browser yet.</h1><p>This local demonstration can only restore an account that completed signup in this browser. It cannot recover a real account or an account on another device.</p><p class="muted">The already-linked identity result is a sample scenario. Return to signup to change the demo details or try another verification outcome.</p></div><button class="button" data-account-resume-signup>Return to signup</button>`);}
const authInput=(label,name,{value='',type='text',autocomplete='off',extras=''}={})=>`<label class="field"><span>${esc(label)}</span><input class="input" name="${esc(name)}" value="${esc(value)}" type="${type}" autocomplete="${autocomplete}" ${extras}></label>`;
const passwordInput=(label,name,autocomplete='new-password')=>authInput(label,name,{type:'password',autocomplete,extras:`required minlength="${autocomplete==='current-password'?1:10}" maxlength="128"`});
const usernameInput=value=>authInput('Username','username',{value,autocomplete:'username',extras:'required minlength="3" maxlength="30" autocapitalize="none" spellcheck="false"'});
const authNote='<p class="auth-demo-note">Local prototype. Use a test password you do not use elsewhere.</p>';
const loginConfigured=ctx=>ctx.connected?!!(ctx.shared?.account?.handle||ctx.state.account?.login?.username):accountLoginConfigured(ctx.state);
const suggestedUsername=s=>normalizeUsername((s.profile?.name||'student').split(' ')[0].replace(/[^a-z0-9]/gi,'')+'.student');
const biometricCopy='<p class="muted auth-device-copy">Your phone verifies you with its face, fingerprint or screen lock. Lumo never receives your biometric data.</p>';
function access(ctx){
  if(ctx.state.onboardingDone!==true&&!ctx.connected)return noSavedAccount(ctx);
  const a=ensureAccountState(ctx.state),configured=ctx.connected||loginConfigured(ctx),bio=a.biometrics;
  if(ctx.connected&&!a.login)a.login={username:''};
  const name=String(ctx.state.profile?.name||'friend').trim().split(/\s+/)[0].slice(0,32)||'friend';
  const enrolled=!ctx.connected&&configured&&!!bio?.credential&&bio.loginEnabled;
  return frame(ctx,'Welcome back',`<div class="auth-welcome" data-auth-access data-auth-mode="${enrolled?'checking':'password'}" data-auth-remembered="true"><div class="auth-welcome-brand" aria-label="Lumo">lumo</div><div class="auth-welcome-body"><div class="auth-lux-stage"><img class="auth-welcome-lux" src="/assets/lux-chat-2d.webp" width="112" height="122" alt="Lux, your Lumo buddy"></div><h1 data-auth-greeting>Welcome,<br>${esc(name)}.</h1><p class="auth-welcome-prompt">Ready for your next move?</p>${configured?`<div class="auth-remembered" data-auth-remembered-row><span>@${esc(a.login.username)}</span><button type="button" class="text-button" data-auth-switch-user>Not ${esc(name)}?</button></div>`:''}</div><div class="auth-welcome-actions">${configured?`${enrolled?`<div class="auth-biometric-first" data-auth-biometric-choice><p class="auth-check-status" data-auth-check-status role="status">Checking phone verification…</p><button type="button" class="button" data-account-biometric-login hidden>${icon('scan',22)} Sign in with biometrics</button><p class="error" data-auth-biometric-error role="alert"></p><button type="button" class="text-button auth-password-choice" data-auth-use-password>Use password</button></div>`:''}<form data-account-form="signin" class="auth-login-form" ${enrolled?'hidden':''}><div data-auth-username-field hidden>${usernameInput(a.login.username).replace('name="username"','name="username" disabled')}</div><input type="hidden" name="username" value="${esc(a.login.username)}" data-auth-remembered-username>${passwordInput('Password','password','current-password')}${error}<button class="button">Sign in</button><button type="button" class="text-button auth-forgot" data-account-page="account-recovery">Forgot password?</button><p class="auth-local-account-note" data-auth-local-account-note hidden>${ctx.connected?'Use the username and password for your shared test account.':'This local prototype signs in only to the account saved in this browser.'}</p><button type="button" class="text-button auth-password-choice" data-auth-use-biometrics hidden>Use biometrics instead</button></form>`:`<p class="auth-legacy-message">This saved prototype needs a username and password. Recover your local account to set them up.</p><button type="button" class="button" data-account-page="account-recovery">Set up my sign-in</button>`}<p class="auth-welcome-footnote">${ctx.connected?'Shared test account':'Local prototype'} · Use test credentials only.</p></div></div>`);
}
function loginSetup(ctx){
  if(ctx.connected)return frame(ctx,'Login details',`<div class="auth-intro"><h1>Your way back in.</h1><p>Your Lumo username is <strong>@${esc(ctx.shared?.account?.handle||ctx.state.account?.login?.username||'')}</strong>.</p><p>Share it so other Lumo users can find you and send you money. Your password is private and signs you in. Changing login details is not available in this test release.</p></div>${button('Security & access','account-security')}`);
  if(ctx.state.onboardingDone!==true)return noSavedAccount(ctx);
  const a=ensureAccountState(ctx.state);
  if(a.signedOut)return access(ctx);
  const configured=loginConfigured(ctx);
  return frame(ctx,configured?'Login details':'Set up your login',`<div class="auth-intro"><h1>${configured?'Your way back in.':'Make it yours.'}</h1><p>${configured?'Update how you sign in.':'Choose a username and password for signing in.'}</p></div><form data-account-form="${configured?'login-change':'login-setup'}">${usernameInput(a.login?.username||suggestedUsername(ctx.state))}${configured?passwordInput('Current password','currentPassword','current-password'):''}${passwordInput(configured?'New password':'Password','password')}${passwordInput('Confirm password','confirmPassword')}${!configured?pinInput('Current transaction PIN','currentPin'):''}<p class="auth-separation">Use at least 10 characters. Your password is separate from your four-digit transaction PIN.</p>${error}<button class="button">${configured?'Update login details':'Save login details'}</button></form>${authNote}`);
}
function enrollmentForm(ctx,{reactivate=false,hidden=false}={}){
  const bio=ensureAccountState(ctx.state).biometrics||{},enrolled=!!bio.credential;
  return `<form data-account-form="biometric-enroll" data-biometric-enrollment ${hidden?'hidden':''}>${reactivate?'<p class="muted">Set up a fresh phone verification. Your saved choice changes only after your password and phone both confirm it.</p>':''}<label class="account-check auth-preference"><input type="checkbox" name="loginEnabled" ${enrolled?bio.loginEnabled?'checked':'':'checked'}><span><strong>Sign in</strong><small>Password is your backup.</small></span></label><label class="account-check auth-preference"><input type="checkbox" name="paymentsEnabled" ${enrolled?bio.paymentsEnabled?'checked':'':'checked'}><span><strong>Approve transactions</strong><small>Transaction PIN is your backup.</small></span></label>${authInput('Confirm your password','currentPassword',{type:'password',autocomplete:'current-password',extras:'required maxlength="128"'})}${error}<button class="button" data-device-enroll>${reactivate?'Set up phone verification again':'Activate phone biometrics'}</button>${reactivate?'<button type="button" class="text-button" data-account-biometric-reactivate-cancel>Keep my saved setup</button>':''}</form>`;
}
function biometricsSection(ctx){
  if(ctx.connected)return `<section class="auth-security-block"><div class="auth-block-heading"><h2>Phone biometrics</h2><span class="auth-status">Not available yet</span></div><p class="muted">Browser biometrics are not connected to shared account authorisation in this test release. Use your password to sign in and your transaction PIN to approve money moves.</p></section>`;
  const a=ensureAccountState(ctx.state),bio=a.biometrics||{},enrolled=!!bio.credential;
  if(!loginConfigured(ctx))return `<section class="auth-security-block"><h2>Phone biometrics</h2><p class="muted">Set up your login first, then choose how your phone can verify you.</p>${button('Set up login','account-login-setup')}</section>`;
  const preferences=enrolled?`<form data-account-form="biometric-preferences"><label class="account-check auth-preference"><input type="checkbox" name="loginEnabled" ${bio.loginEnabled?'checked':''}><span><strong>Sign in</strong><small>Password is your backup.</small></span></label><label class="account-check auth-preference"><input type="checkbox" name="paymentsEnabled" ${bio.paymentsEnabled?'checked':''}><span><strong>Approve transactions</strong><small>Transaction PIN is your backup.</small></span></label>${authInput('Password to enable a choice','currentPassword',{type:'password',autocomplete:'current-password',extras:'maxlength="128"'})}${error}<button class="button secondary">Save biometric choices</button></form>`:'';
  return `<section class="auth-security-block" data-biometric-settings><div class="auth-block-heading"><h2>Phone biometrics</h2><span class="auth-status" data-device-enrollment-state>${enrolled?'Saved on this browser':'Optional'}</span></div>${biometricCopy}<p class="auth-device-status muted" data-device-status role="status"></p>${preferences}${enrollmentForm(ctx,{reactivate:enrolled,hidden:enrolled})}${enrolled?'<button type="button" class="text-button" data-account-biometric-reactivate>Set up phone verification again</button><button class="text-button" data-account-biometric-disable>Remove from this device</button>':''}<p class="auth-demo-note">Real device verification for this local prototype. Login and money records remain in this browser.</p></section>`;
}
function security(ctx){
  const a=ensureAccountState(ctx.state),configured=loginConfigured(ctx);
  return frame(ctx,'Security & access',`<div class="auth-intro"><h1>Your account. Your keys.</h1><p>One way to sign in. A separate check for your money.</p></div><section class="auth-security-block"><div class="auth-block-heading"><h2>Login details</h2><span class="auth-status">${configured?'Set up':'Needed'}</span></div><p class="muted">${configured?`Lumo username <strong>@${esc(a.login.username)}</strong>`:'A username and password for signing in.'}</p>${ctx.connected?'<p class="muted">Share your @username to receive money. Keep your password and PIN private. Changing login details is not available in this test release.</p>':button(configured?'Change login details':'Set up login','account-login-setup')}</section>${biometricsSection(ctx)}<details class="account-disclosure"><summary>Transaction PIN</summary><div class="account-disclosure-body"><p>Use this four-digit PIN to approve transactions when phone biometrics are off or unavailable.</p><form data-account-form="pin">${pinInput('Current transaction PIN','currentPin')}${pinInput('New transaction PIN','newPin')}${pinInput('Confirm transaction PIN','confirmPin')}${error}<button class="button secondary">Update transaction PIN</button></form>${ctx.connected?'<button type="button" class="text-button" data-account-test-pin-repair hidden>Set up my test PIN</button><p class="muted" data-account-test-pin-repair-status role="status" hidden></p>':''}</div></details><div class="auth-security-links">${row({emoji:icon('phone'),title:'Devices',sub:ctx.connected?'This signed-in browser':'This browser and sample sessions',action:'account-devices'})}${row({emoji:icon('help'),title:'Forgot your password?',sub:ctx.connected?'Recovery availability for shared accounts':'Recover your local login',action:'account-recovery'})}</div><details class="account-disclosure"><summary>Recent security activity</summary><div class="account-disclosure-body">${a.securityEvents.slice(0,5).map(e=>row({emoji:icon('lock'),title:e.detail,sub:new Date(e.at).toLocaleString('en-GH')})).join('')||'<p class="muted">No security changes yet.</p>'}</div></details><button class="button secondary" data-account-signout>${icon('logout',18)} Sign out</button>`);
}
function recovery(ctx){
  if(ctx.connected)return frame(ctx,'Recover your login',`<div class="auth-intro"><h1>Let’s get you back.</h1><p>Password recovery for shared test accounts is not available in this release. There is no SMS recovery code, and creating another account will not recover your existing money or records.</p><p class="muted">If you are still signed in on another device, keep that session open. Your existing username and password remain the way to sign in.</p></div>${button('Back to sign in','account-access')}`);
  if(ctx.state.onboardingDone!==true)return noSavedAccount(ctx);
  const a=ensureAccountState(ctx.state),r=a.recovery,waiting=r?.status==='code-sent';
  return frame(ctx,'Recover your login',`<div class="auth-intro"><h1>Let’s get you back.</h1><p>Reset your login password. Your transaction PIN and money stay as they are.</p></div>${!waiting?`<form data-account-form="recovery-start">${input('Registered demo phone number','phone','','tel','required inputmode="tel" placeholder="024 000 0000"')}${r?`<p class="notice"><span>The last demo recovery is ${esc(r.status)}. Request a fresh code.</span></p>`:''}${error}<button class="button">Get a demo recovery code</button></form>`:`<div class="notice"><span>Your demo code is <strong>123456</strong>. It expires in five minutes. No SMS was sent.</span></div><form data-account-form="recovery-finish">${input('Six-digit demo code','code','','text','inputmode="numeric" maxlength="6" required')}${usernameInput(a.login?.username||suggestedUsername(ctx.state))}${passwordInput('New password','password')}${passwordInput('Confirm password','confirmPassword')}<p class="muted">Phone biometrics will be removed. Activate them again after recovery.</p>${error}<button class="button">Reset login password</button></form><button class="text-button" data-account-recovery-resend>Request another demo code</button>`}${button('Back to sign in','account-access')}${authNote}`);
}
function devices(ctx){if(ctx.connected)return frame(ctx,'Your devices',`<h1>This signed-in browser.</h1><p class="muted">This browser uses your shared account session. Viewing or revoking other sessions is not available in this test release.</p>${button('Security & access','account-security')}`);const a=ensureAccountState(ctx.state);return frame(ctx,'Your devices',`<h1>Who’s signed in?</h1><p class="muted">This prototype runs in this browser. The extra device below is a testing simulation.</p><div class="panel">${a.devices.map(d=>`<div class="account-device">${icon('phone',24)}<div><strong>${esc(d.name)}</strong><p class="muted">${d.current?'You are here':d.simulated?'Participant simulation':''} · ${esc(d.status)}</p><p class="muted">Last recorded ${dateLabel(d.lastSeenAt)}</p></div>${!d.current&&d.status==='active'?`<button class="text-button" data-account-revoke="${esc(d.id)}">Sign out</button>`:''}</div>`).join('')}</div><details class="account-simulation"><summary>Device simulation</summary><p>Add a sample campus laptop, then revoke it to test this control. No other browser is actually connected.</p><button class="button secondary" data-account-device-add>Add sample device</button></details>`);}
const recordDateField=(label,name,value)=>`<div class="field"><span>${esc(label)}</span><input type="hidden" name="${name}" value="${esc(value)}"><button type="button" class="input account-statement-date" data-account-date="${name}" aria-label="Choose ${label.toLowerCase()} date, ${esc(recordDateLabel(value))}" aria-haspopup="dialog"><span data-account-date-value>${esc(recordDateLabel(value))}</span>${icon('calendar',21)}</button></div>`;
function statements(ctx){const txs=ctx.state.transactions||[],now=new Date().toISOString().slice(0,10),from=ctx.draft.accountStatement?.from??now.slice(0,7)+'-01',to=ctx.draft.accountStatement?.to??now;return frame(ctx,'Your records',`<h1>Download a statement.</h1><p class="muted">Choose your dates. Completed and unresolved entries keep their status.</p><form data-account-form="statement" novalidate>${recordDateField('From','from',from)}${recordDateField('To','to',to)}${error}<button class="button">${icon('download',19)} Download CSV statement</button><p class="account-download-status" data-statement-status role="status" aria-live="polite"></p></form><details class="account-disclosure"><summary>All saved account data</summary><div class="account-disclosure-body"><p>Balances, transactions, budgets, Money Boxes, IOUs, outside money, recovery and saved support reports.</p><p class="muted">Passwords, device credentials, PINs, access codes, Ghana Card details, selfies, card credentials and private chats are excluded.</p><button class="button secondary" type="button" data-account-export>Download account data</button><p class="account-download-status" data-export-status role="status" aria-live="polite"></p><p class="error" data-export-error role="alert"></p></div></details><p class="muted">${txs.length} financial records ${ctx.connected?'in your latest shared account snapshot':'saved on this browser'}. Files contain your information. Share them only with someone you choose.</p>`);}
function support(ctx){const cases=ensureAccountState(ctx.state).supportCases;return frame(ctx,'Your support reports',`<h1>Keep the details together.</h1><p class="muted">A reference, the payment and your updates. ${ctx.connected?'Reports are saved with your shared test account and can appear on your other signed-in devices. No live support team has been contacted.':'Everything stays on this device in this demo.'}</p>${button('Create a report','account-support-new')}<div class="panel">${cases.length?cases.map(c=>row({emoji:icon('chat'),title:c.title,sub:`${c.reference} · ${c.status} · ${dateLabel(c.updatedAt)}`,action:`account-case:${c.id}`})).join(''):'<div class="account-padded"><h2>Nothing to chase.</h2><p class="muted">If something feels off, save the details here. A report will not change a payment’s outcome.</p></div>'}</div>`);}
function supportNew(ctx,r){const tx=ctx.state.transactions.find(t=>t.id===r.transactionId),funding=ctx.state.fundingAttempts?.find(f=>f.id===r.fundingId),d=getSupportDraft(ctx,r);return frame(ctx,'Talk to us',`<h1>What happened?</h1><p class="muted">A little detail now makes the next step clearer.</p>${tx?`<div class="panel account-padded"><strong>${esc(tx.merchant)} · ${cash(tx.amount)}</strong><p class="muted">${esc(tx.id)} · ${esc(tx.status)}</p></div>`:funding?`<div class="panel account-padded"><strong>Add money · ${cash(funding.amount)}</strong><p class="muted">${esc(funding.reference)} · ${esc(funding.status)}</p></div>`:''}<form data-account-form="support-new">${input('Short title','title',d.title||'','text','maxlength="100" required')}<label class="field"><span>Type of report</span><select class="input" name="category">${['payment','question','idea','bug','privacy'].map(x=>`<option ${x===(d.category||((tx||funding)?'payment':'question'))?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Tell us a little more</span><textarea class="input" rows="5" name="body" maxlength="2000" required>${esc(d.body||'')}</textarea></label><p class="muted">Keep PINs, codes, card details and Ghana Card information out of this report.</p>${error}<button class="button">${ctx.connected?'Save my report':'Save my demo report'}</button></form>`);}
const supportUpdateText=(ctx,u)=>supportRecordText(u,{connected:ctx.connected===true});
function supportDetail(ctx,r){const c=ensureAccountState(ctx.state).supportCases.find(c=>c.id===r.id);if(!c)return frame(ctx,'Report not found',`<h1>That report is not here.</h1>${button('Your reports','account-support')}`);const tx=ctx.state.transactions.find(t=>t.id===c.transactionId),funding=ctx.state.fundingAttempts?.find(f=>f.id===c.fundingId);return frame(ctx,c.reference,`<span class="eyebrow">${esc(c.status.toUpperCase())} · ${ctx.connected?'SHARED TEST ACCOUNT':'LOCAL DEMO'}</span><h1>${esc(c.title)}</h1><p>${esc(c.body)}</p>${tx?`<button class="panel account-padded account-linked" data-account-transaction="${esc(tx.id)}"><strong>${esc(tx.merchant)} · ${cash(tx.amount)}</strong><span>${esc(tx.status)} · ${esc(tx.id)}</span></button>`:funding?`<button class="panel account-padded account-linked" data-account-funding="${esc(funding.id)}"><strong>Add money · ${cash(funding.amount)}</strong><span>${esc(funding.status)} · ${esc(funding.reference)}</span></button>`:''}<div class="section-label">Updates</div><ol class="account-timeline">${c.updates.map(u=>`<li><small>${esc(u.kind==='you'?'You':u.kind==='simulation'?'Participant simulation':'Lumo')} · ${dateLabel(u.at)}</small><p>${esc(supportUpdateText(ctx,u))}</p></li>`).join('')}</ol><form data-account-form="support-update"><label class="field"><span>${c.status==='resolved'?'Reopen with a note':'Add a note'}</span><textarea class="input" rows="3" name="body" maxlength="2000" required>${esc(getSupportDraft(ctx,r).body||'')}</textarea></label>${error}<button class="button">${c.status==='resolved'?'Reopen report':'Add update'}</button></form><button class="button secondary" data-account-report-download="${esc(c.id)}">Download report</button>${ctx.connected?'':`<details class="account-simulation"><summary>Support status simulation</summary><p>No live agent is connected. These controls demonstrate report updates.</p><div class="inline-actions">${['reviewing','resolved','open'].map(status=>`<button class="chip" data-account-case-status="${status}">${status==='open'?'Reopen':status==='resolved'?'Resolve':'Under review'}</button>`).join('')}</div></details>`}${r.returnTo?'<button class="button secondary" data-account-return>Return to what I was doing</button>':''}`);}
function privacy(ctx){const a=ensureAccountState(ctx.state);return frame(ctx,'Your privacy choices',`<h1>Your information. Your say.</h1><p class="muted">${ctx.connected?'These preferences are saved with your shared test account and sync after sign-in on another device.':'These preferences are saved locally.'} No marketing service or external analytics is connected to this prototype.</p><div class="panel">${[['personalisation','Personalised learning','Use my recorded activity in Money IQ and learning examples. Ask Lux still uses the authorised money details needed to answer questions I choose to ask.'],['marketing','Marketing messages','Record my preference for future product messages.']].map(([key,label,sub])=>`<label class="account-check account-padded"><input type="checkbox" data-account-privacy="${key}" ${a.privacy[key]?'checked':''}><span><strong>${label}</strong><small>${sub}</small></span></label>`).join('')}</div><div class="panel account-padded"><h2>Request data deletion</h2><p>A request should be reviewed before records are removed. Financial history may need to be retained. ${ctx.connected?'This test release saves your request with your shared account. No live support team is notified and nothing is deleted.':'This demo records your request without sending or deleting anything.'}</p>${a.requests.some(r=>r.type==='deletion'&&r.status==='requested')?a.requests.filter(r=>r.type==='deletion'&&r.status==='requested').map(r=>`<p>Request recorded ${dateLabel(r.at)}</p><button class="button secondary" data-account-cancel-deletion="${esc(r.id)}">${ctx.connected?'Cancel request':'Cancel local request'}</button>`).join(''):`<button class="button secondary" data-account-delete-request>${ctx.connected?'Record a deletion request':'Record a demo deletion request'}</button>`}</div><div class="panel account-padded"><h2>What this prototype stores</h2><p>${ctx.connected?'Your connected test-money records, plans, Money Boxes, group messages, support reports and privacy choices are stored in your shared account. Clearing browser data removes this device’s saved sign-in and local drafts; it does not delete your shared account records.':'Your sample money, messages and preferences stay in this browser.'} Private Ask Lux conversations are kept for this tab’s session, including refreshes, and are excluded from account data exports. Closing the tab can remove them. Ghana Card captures and selfies are memory-only. ${ctx.connected?'':'Clearing browser data removes saved progress.'}</p>${button('Download my records','account-statements')}</div>`);}
function close(ctx){const a=ensureAccountState(ctx.state),blockers=closureBlockers(ctx.state);if(a.status==='closed')return frame(ctx,'Account closed',`<div class="account-intro">${icon('check',42)}<h1>Your records are still here.</h1><p>Closed on ${dateLabel(a.closedAt)}. Financial actions are disabled. You can view history, download records or keep a support report.</p></div>${button('Download records','account-statements')}${button('Your support reports','account-support')}`);return frame(ctx,'Before you go',`<h1>Leave with everything clear.</h1><p class="muted">Closing this ${ctx.connected?'shared test':'sample'} account stops new money actions and keeps its financial records available to read and export.</p>${blockers.length?`<div class="section-label">A few things to finish first</div><div class="panel">${blockers.map(b=>`<button class="row" data-account-blocker="${esc(b.code)}"><span class="row-icon">${icon('info')}</span><span class="row-copy"><span class="row-title">${esc(b.title)}</span><span class="row-sub">${esc(b.detail)}</span></span>${icon('chevron',16)}</button>`).join('')}</div>`:`<div class="notice"><span>No remaining money or unresolved items were found. Download your records before continuing.</span></div><form data-account-form="close">${input('Type CLOSE','confirm','','text','required autocomplete="off"')}${ctx.connected?'<p class="muted">Your transaction PIN is requested once in the confirmation step.</p>':pinInput('Your demo PIN','pin')}${error}<button class="button">Close this ${ctx.connected?'test':'demo'} account</button></form>`}${button('Download my records','account-statements')}`);}
