ctx.$$('[data-account-revoke]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountRevokeDevice',{deviceId:b.dataset.accountRevoke}));}));ctx.$$('[data-account-device-add]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountAddDemoDevice'));}));ctx.$$('[data-account-recovery-resend]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountStartRecovery',{phone:ctx.state.profile.phone}));}));ctx.$$('[data-account-privacy]').forEach(b=>b.onchange= ()=>runActionFlow(function*(){return (yield action('accountPrivacy',{preference:b.dataset.accountPrivacy,enabled:b.checked}));}));ctx.$$('[data-account-delete-request]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountDeletionRequest'));}));ctx.$$('[data-account-cancel-deletion]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountCancelDeletion',{requestId:b.dataset.accountCancelDeletion}));}));ctx.$$('[data-account-case-status]').forEach(b=>b.onclick= ()=>runActionFlow(function*(){return (yield action('accountSupportSimulate',{caseId:r.id,status:b.dataset.accountCaseStatus}));}));ctx.$$('[data-account-report-download]').forEach(b=>b.onclick=()=>downloadAccountFile('Lumo-support-report.txt',supportSummary(ctx.state,b.dataset.accountReportDownload,{connected:ctx.connected===true})));ctx.$$('[data-account-transaction]').forEach(b=>b.onclick=()=>ctx.go({section:'pay',page:'transaction',id:b.dataset.accountTransaction,returnTo:r}));ctx.$$('[data-account-funding]').forEach(b=>b.onclick=()=>ctx.go({section:'pay',page:'funding-detail',id:b.dataset.accountFunding,returnTo:r}));ctx.$$('[data-account-return]').forEach(b=>b.onclick=()=>ctx.go(r.returnTo||{section:'life',page:'account-support'}));ctx.$$('[data-account-blocker]').forEach(b=>b.onclick=()=>{const blocker=closureBlockers(ctx.state).find(x=>x.code===b.dataset.accountBlocker);if(blocker)ctx.go(blocker.route);});const recordsCle